<script module lang="ts">
    export const layout = { breadcrumbs: [{ title: 'Biaya', href: '/owner/expenses' }, { title: 'Detail biaya', href: '#' }] };
</script>

<script lang="ts">
    import { Form, Link } from '@inertiajs/svelte';
    import AppHead from '@/components/AppHead.svelte';
    import InputError from '@/components/InputError.svelte';
    import { Button } from '@/components/ui/button';
    import { Input } from '@/components/ui/input';
    let { expense, idempotency_key }: { expense: { id: number; kind: string; category: string; description: string; amount_due_rupiah: number; paid_rupiah: number; outstanding_rupiah: number; incurred_on: string; property: { name: string } | null; room: { code: string } | null; maintenance_job: { id: number; category: string; description: string } | null; created_by: string | null; payments: { id: number; kind: string; amount_rupiah: number; occurred_on: string | null; method: string | null; external_reference: string | null; cash_transaction_id: number }[] }; idempotency_key: string } = $props();
    const money = (value: number) => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(value);
</script>

<AppHead title={`Biaya ${expense.category}`} />
<main class="mx-auto w-full max-w-4xl space-y-6 p-4 md:p-8">
    <header class="flex flex-wrap items-start justify-between gap-4"><div class="space-y-2"><p class="text-sm font-medium text-muted-foreground">{expense.property?.name ?? 'Biaya'}{expense.room ? ` · Kamar ${expense.room.code}` : ''}</p><h1 class="text-3xl font-semibold tracking-tight">{expense.category}</h1><p class="text-sm text-muted-foreground">{expense.description}</p></div><Link href="/owner/expenses" class="inline-flex rounded-md border px-4 py-2 text-sm">Daftar biaya</Link></header>
    <section class="grid gap-4 sm:grid-cols-3"><article class="rounded-xl border bg-card p-5"><p class="text-sm text-muted-foreground">Kewajiban</p><p class="mt-2 text-xl font-semibold">{money(expense.amount_due_rupiah)}</p></article><article class="rounded-xl border bg-card p-5"><p class="text-sm text-muted-foreground">Kas keluar aktual</p><p class="mt-2 text-xl font-semibold">{money(expense.paid_rupiah)}</p></article><article class="rounded-xl border bg-card p-5"><p class="text-sm text-muted-foreground">Belum dibayar</p><p class="mt-2 text-xl font-semibold">{money(expense.outstanding_rupiah)}</p></article></section>
    {#if expense.outstanding_rupiah > 0}<section class="space-y-4 rounded-xl border bg-card p-5 shadow-sm"><div><h2 class="font-semibold">Catat pembayaran biaya</h2><p class="mt-1 text-sm text-muted-foreground">Nominal dibatasi pada sisa kewajiban dan tercatat sebagai kas keluar aktual.</p></div><Form action={`/owner/expenses/${expense.id}/payments`} method="post" class="grid gap-4 sm:grid-cols-2">{#snippet children({ errors, processing })}<input type="hidden" name="idempotency_key" value={idempotency_key} /><div class="space-y-2"><label for="amount_rupiah" class="text-sm font-medium">Dibayar (Rupiah)</label><Input id="amount_rupiah" name="amount_rupiah" type="number" min={1} max={expense.outstanding_rupiah} step={1} required /><InputError message={errors.amount_rupiah} /></div><div class="space-y-2"><label for="occurred_on" class="text-sm font-medium">Tanggal dibayar</label><Input id="occurred_on" name="occurred_on" type="date" required /><InputError message={errors.occurred_on} /></div><div class="space-y-2"><label for="method" class="text-sm font-medium">Metode</label><select id="method" name="method" required class="h-10 w-full rounded-md border bg-background px-3 text-sm"><option value="bank_transfer">Transfer bank</option><option value="cash">Tunai</option><option value="e_wallet">Dompet digital</option><option value="other">Lainnya</option></select><InputError message={errors.method} /></div><div class="space-y-2"><label for="external_reference" class="text-sm font-medium">Referensi</label><Input id="external_reference" name="external_reference" maxlength={160} /><InputError message={errors.external_reference} /></div><InputError message={errors.expense} /><div class="sm:col-span-2 flex justify-end"><Button type="submit" disabled={processing}>{processing ? 'Mencatat…' : 'Catat pembayaran'}</Button></div>{/snippet}</Form></section>{/if}
    <section class="rounded-xl border bg-card p-5"><h2 class="font-semibold">Riwayat pembayaran</h2>{#if expense.payments.length === 0}<p class="mt-3 text-sm text-muted-foreground">Belum ada pembayaran. Nilai kewajiban tidak dihitung sebagai kas keluar.</p>{:else}<div class="mt-3 divide-y">{#each expense.payments as payment (payment.id)}<Link href={`/owner/payments/${payment.cash_transaction_id}`} class="flex justify-between gap-4 py-3 text-sm"><span>{payment.occurred_on ?? 'Tanggal tidak tersedia'} · {payment.method ?? 'Transfer'} · {payment.kind}</span><span>{money(payment.amount_rupiah)}</span></Link>{/each}</div>{/if}</section>
</main>
